//! A Rust inference bridge with pluggable native backends.
//!
//! The safe Rust API lives here. The raw FFI bindings are generated by
//! `build.rs` and the C++ bridge library is loaded at runtime through
//! [`dll::Bridge`] (never linked at build time).
//!
//! The native bridge is **not** feature-gated: `build.rs` always generates the
//! bindings, so `libclang` and `cpp/include/public/rsinference.h` are required
//! to build this crate.

pub mod dll;
pub mod engine;
pub mod error;
pub mod ffi;

pub use dll::Bridge;
pub use engine::{Engine, EngineType};
pub use error::{InferError, InferResult};
